<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Reward coupons · Crea-Biz EV</title><script src="/theme.js"></script><link rel="stylesheet" href="/platform.css"><link rel="stylesheet" href="/retail-partners.css"><script src="/admin-reward-coupons.js" defer></script></head><body><main class="retail-wrap"><header><a href="/" data-t="home">Workspace</a><select id="language" aria-label="Language / اللغة"><option value="en">English</option><option value="ar">العربية</option></select><select id="theme-choice" aria-label="Theme / المظهر"><option value="system">System / النظام</option><option value="light">Light / فاتح</option><option value="dark">Dark / داكن</option></select></header><h1 data-t="title">Noncash reward coupons</h1><p data-t="notice">Coupons reserve an existing manual noncash reward. They never discount a charging invoice, move money or prove delivery. Commercial activation requires review.</p><p id="status" role="status" aria-live="polite"></p><section id="workspace" hidden><h2 data-t="catalog">Published coupons</h2><button id="refresh" data-t="refresh">Refresh</button><div id="coupons"></div><nav aria-label="Coupon pagination"><button id="previous" data-t="previous">Previous</button><bdi id="page"></bdi><button id="next" data-t="next">Next</button></nav><details id="editor"><summary data-t="new">Publish a coupon</summary><p data-t="privateCode">Distribute your code privately. The server retains only its hash; it cannot display the code again. Existing claims survive revocation and remain pending manual fulfillment.</p><button id="rewards-refresh" data-t="rewardsRefresh">Load canonical reward choices</button><div id="rewards"></div><nav aria-label="Reward pagination"><button id="reward-previous" data-t="previous">Previous</button><bdi id="reward-page"></bdi><button id="reward-next" data-t="next">Next</button></nav><form id="coupon-form"><label><span data-t="reward">Reward ID</span><input name="reward_id" type="number" min="1" max="9007199254740991" required readonly></label><label><span data-t="code">Coupon code (12–40 uppercase letters, digits or hyphens)</span><input name="code" type="password" autocomplete="off" pattern="[A-Z0-9-]{12,40}" minlength="12" maxlength="40" required dir="ltr"></label><label><span data-t="limit">Total claim limit</span><input name="claim_limit" type="number" min="1" max="1000000" required></label><label><span data-t="perUser">Claims per member</span><input name="per_user_limit" type="number" min="1" max="100" required></label><label><span data-t="starts">Starts at (UTC)</span><input name="starts_at" type="datetime-local" required></label><label><span data-t="ends">Ends at (UTC)</span><input name="ends_at" type="datetime-local" required></label><button data-t="publish">Publish coupon</button><button id="resolve" type="button" data-t="resolve">Find saved publication</button><button id="discard" type="button" data-t="discard">Clear private draft</button></form></details></section></main></body></html>
